namespace Clc.Polaris.Api.UnitTests.SerializationAndModels.Json.Serialization { [TestClass][UnitTest] public sealed class JobsPurchaseOrdersCreateDataTests { [TestMethod] public void RoundTripsDocumentedShape() { var data = new JobsPurchaseOrdersCreateData { PONumber = "po", PostbackURL = "url", MARCLineItems = new() { new JobsPurchaseOrdersMarcLineItem { MarcRecord = new MarcRecord { Leader = "leader", ControlFields = new() { new MarcControlField { Tag = "001", Value = "1" } }, DataFields = new() { new MarcDataField { Tag = "245", Subfields = new() { new MarcSubfield { Code = "a", Value = "title" } } } } } } } }; var json = System.Text.Json.JsonSerializer.Serialize(data); Assert.Contains("PONumber", json); Assert.Contains("PostbackURL", json); Assert.Contains("MARCLineItems", json); Assert.Contains("ControlFields", json); Assert.Contains("Subfields", json); } } }
